from flask import Flask, request, send_file, jsonify
import os
import logging
import subprocess
import urllib.request

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)

BASE_DIR = '/app/documents'
METADATA_URL = 'http://169.254.170.2/v2/credentials/'

def get_task_credentials():
    """Fetch ECS task role credentials from metadata endpoint"""
    try:
        relative_uri = os.environ.get('AWS_CONTAINER_CREDENTIALS_RELATIVE_URI', '')
        resp = urllib.request.urlopen(METADATA_URL + relative_uri, timeout=2)
        return resp.read().decode()
    except Exception as e:
        logging.warning(f"Could not fetch credentials: {e}")
        return None

def sanitize_filename(filename):
    """Remove null bytes and normalize"""
    filename = filename.replace('\x00', '')
    # Strip leading slashes to prevent absolute paths
    filename = filename.lstrip('/')
    return filename

@app.route('/api/v1/documents/<path:filepath>', methods=['GET'])
def serve_document(filepath):
    """Serve documents from the documents directory"""
    cleaned = sanitize_filename(filepath)

    # Security: reject if path contains obvious traversal
    if cleaned.startswith('..'):
        return jsonify({'error': 'Invalid path'}), 403

    full_path = os.path.join(BASE_DIR, cleaned)

    # Additional check: verify the resolved path
    # Note: os.path.join with relative '../' still resolves within join logic
    if not os.path.exists(full_path):
        return jsonify({'error': 'File not found'}), 404

    logging.info(f"Serving file: {full_path}")
    return send_file(full_path)

@app.route('/api/v1/documents/metadata', methods=['GET'])
def get_metadata():
    """Return document service metadata including task info"""
    creds = get_task_credentials()
    task_info = {
        'service': 'document-server',
        'version': '2.3.1',
        'base_dir': BASE_DIR,
        'task_arn': os.environ.get('ECS_TASK_ARN', 'unknown'),
        'has_credentials': creds is not None
    }
    return jsonify(task_info)

@app.route('/api/v1/health', methods=['GET'])
def health_check():
    return jsonify({'status': 'healthy'}), 200

@app.route('/api/v1/documents/search', methods=['POST'])
def search_documents():
    """Search for documents by pattern using find command"""
    data = request.get_json()
    pattern = data.get('pattern', '*')

    # Use subprocess to find files matching pattern
    try:
        result = subprocess.run(
            ['find', BASE_DIR, '-name', pattern, '-type', 'f'],
            capture_output=True, text=True, timeout=5
        )
        files = result.stdout.strip().split('\n') if result.stdout.strip() else []
        return jsonify({'files': files})
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Search timeout'}), 504

if __name__ == '__main__':
    os.makedirs(BASE_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
